from __future__ import annotations

import json

import pytest

from gitseed.cli import OllamaGrader


class ResponseTransport:
    def __init__(self, response: str) -> None:
        self.response = response

    def request(self, method, url, data=None, extra_headers=None):
        return 200, {}, json.dumps({"response": self.response}).encode()


def maliciousness_result(response: str) -> bool:
    grader = OllamaGrader(
        "contract-test-model",
        ResponseTransport(response),
        environ={},
    )
    return grader.flags_malicious("repository: example/tool\n")


@pytest.mark.parametrize(
    ("response", "expected"),
    [
        (json.dumps({"malicious": True}), True),
        (json.dumps({"malicious": False}), False),
    ],
)
def test_maliciousness_returns_the_model_boolean(response: str, expected: bool) -> None:
    assert maliciousness_result(response) is expected


@pytest.mark.parametrize(
    "response",
    [
        json.dumps({"malicious": "false"}),
        json.dumps({"malicious": 0}),
        json.dumps({}),
        json.dumps([]),
        "{not valid JSON",
    ],
    ids=["string", "numeric", "missing", "non-object", "malformed-json"],
)
def test_maliciousness_rejects_invalid_model_contracts(response: str) -> None:
    with pytest.raises(Exception) as raised:
        maliciousness_result(response)

    message = str(raised.value).lower()
    assert "malicious" in message
    assert "boolean" in message
